(function(){var root=document.querySelector(".fnl");if(!root)return;var sets=[].slice.call(root.querySelectorAll(".fnl__set"));if(!sets.length)return;var ladder=root.querySelector(".fnl__steps");var count=root.querySelector(".fnl__count");var hidden=root.querySelector("#fnl-prompt");if(hidden)hidden.name="prompt";root.classList.add("js-fnl");var at=0;[].slice.call(root.querySelectorAll("[required]")).forEach(function(el){el.setAttribute("data-req","1");el.removeAttribute("required")});[].slice.call(root.querySelectorAll("input[type=url], input[type=email], input[type=tel]")).forEach(function(el){el.setAttribute("data-type",el.type)});function syncValidation(){[].slice.call(root.querySelectorAll("[data-req], [data-type]")).forEach(function(el){var mine=el.closest(".fnl__set")===sets[at];if(el.hasAttribute("data-req")){if(mine)el.setAttribute("required","required");else el.removeAttribute("required")}if(el.hasAttribute("data-type")){el.type=mine?el.getAttribute("data-type"):"text"}})}function buildLadder(){if(!ladder)return;ladder.innerHTML=sets.map(function(s,i){return'<li style="--s:'+i+'"><b>'+("0"+(i+1)).slice(-2)+"</b><span>"+(s.getAttribute("data-tag")||"")+"</span></li>"}).join("")}function drawLadder(){if(ladder){[].slice.call(ladder.children).forEach(function(li,i){li.classList.toggle("is-done",i<at);li.classList.toggle("is-at",i===at)})}if(count){count.innerHTML="Step <b>"+(at+1)+"</b> of "+sets.length}}function show(i){at=Math.max(0,Math.min(sets.length-1,i));sets.forEach(function(s,n){s.classList.toggle("is-at",n===at)});drawLadder();syncValidation();var focusable=sets[at].querySelector("input:not([type=hidden]), textarea, select");if(focusable&&focusable.type!=="radio")focusable.focus();var top=root.getBoundingClientRect().top+window.pageYOffset-12;if(window.pageYOffset>top)window.scrollTo(0,top)}function answered(set){var url=set.querySelector("input[type=url]");if(url&&(!url.value.trim()||!url.checkValidity()))return false;var radios=set.querySelectorAll("input[type=radio]");if(!radios.length)return true;for(var i=0;i<radios.length;i++)if(radios[i].checked)return true;return false}function nudge(set){var hint=set.querySelector(".fnl__hint");if(!hint)return;var was=hint.textContent;hint.textContent="Choose one to continue";setTimeout(function(){hint.textContent=was},1800)}function compose(){if(!hidden)return;var lines=[];sets.forEach(function(s){var lab=s.getAttribute("data-note");if(!lab)return;var picked=s.querySelector("input[type=radio]:checked");if(picked)lines.push(lab+": "+picked.value)});var day=root.querySelector(".fnl__chip.is-sel");var slot=root.querySelector(".fnl__slot.is-sel");if(day&&slot){lines.push("Requested call: "+day.getAttribute("data-full")+", "+slot.textContent.trim()+" (Melbourne)")}hidden.value=lines.length?"Answers from the free report funnel\n\n"+lines.join("\n"):"Free AI visibility report requested from the funnel."}root.addEventListener("click",function(ev){var next=ev.target.closest("[data-next]");if(next){ev.preventDefault();if(!answered(sets[at])){nudge(sets[at]);return}show(at+1);return}var back=ev.target.closest("[data-back]");if(back){ev.preventDefault();show(at-1);return}var chip=ev.target.closest(".fnl__chip");if(chip){ev.preventDefault();root.querySelectorAll(".fnl__chip").forEach(function(c){c.classList.remove("is-sel");c.setAttribute("aria-pressed","false")});chip.classList.add("is-sel");chip.setAttribute("aria-pressed","true");compose();syncBook();return}var slot=ev.target.closest(".fnl__slot");if(slot){ev.preventDefault();root.querySelectorAll(".fnl__slot").forEach(function(c){c.classList.remove("is-sel");c.setAttribute("aria-pressed","false")});slot.classList.add("is-sel");slot.setAttribute("aria-pressed","true");compose();syncBook();return}});root.addEventListener("change",function(ev){if(ev.target.type!=="radio"){compose();return}compose();var set=ev.target.closest(".fnl__set");if(!set||set!==sets[at])return;if(at<sets.length-1)setTimeout(function(){show(at+1)},260)});root.addEventListener("keydown",function(ev){var t=ev.target;var tag=(t.tagName||"").toLowerCase();var typing=tag==="input"||tag==="textarea"||tag==="select";var native=tag==="button"||tag==="a";if(ev.key==="Enter"){if(native)return;if(typing&&t.type!=="url"&&t.type!=="text")return;ev.preventDefault();if(answered(sets[at]))show(at+1);else nudge(sets[at]);return}if(typing||native)return;if(/^[1-9]$/.test(ev.key)){var radios=sets[at].querySelectorAll("input[type=radio]");var i=Number(ev.key)-1;if(radios[i]){radios[i].checked=true;radios[i].dispatchEvent(new Event("change",{bubbles:true}))}}});var DOW=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];var MON=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];function buildBook(){var row=root.querySelector(".fnl__chiprow");if(!row)return;var d=new Date;d.setHours(0,0,0,0);var out=[],n=0;while(out.length<8&&n<30){d.setDate(d.getDate()+1);n++;if(d.getDay()===0||d.getDay()===6)continue;var full=DOW[d.getDay()]+" "+d.getDate()+" "+MON[d.getMonth()];out.push('<button type="button" class="fnl__chip" aria-pressed="false" data-full="'+full+'">'+DOW[d.getDay()]+" "+d.getDate()+"<small>"+MON[d.getMonth()]+"</small></button>")}row.innerHTML=out.join("")}function syncBook(){var chosen=root.querySelector(".fnl__chosen");var send=root.querySelector("#fnl-send");var day=root.querySelector(".fnl__chip.is-sel");var slot=root.querySelector(".fnl__slot.is-sel");var both=!!(day&&slot);if(chosen){if(both){chosen.innerHTML="Requesting <b>"+day.getAttribute("data-full")+", "+slot.textContent.trim()+"</b> — Melbourne time. We confirm by email within one business day."}chosen.hidden=!both}if(send){send.textContent=both?"Send the report and request this time":"Send the report"}}buildLadder();buildBook();syncBook();compose();show(0)})();
